<?php
require_once __DIR__.'/Accounts.php';
/** Server-priced account upgrades. Provider balance is not minted into project credit automatically. */
class SaaSCommerce {
    private $accounts;
    public function __construct($accounts=null){$this->accounts=$accounts?:new SaaSAccounts();}
    public function products(){return array_filter($this->accounts->state()['catalog']??[],static fn($p)=>!empty($p['enabled']));}
    public function saveProduct($input){if(!isMainAdmin())throw new RuntimeException('مدیریت تعرفه فقط با تیم مرکزی است.');$id=$input['id']??'';$kind=$input['kind']??'';$name=trim($input['name']??'');$amount=(int)($input['price_toman']??0);$units=(int)($input['units']??0);if(!SaaSAccounts::validId($id)||!in_array($kind,['credits','projects','seats','storage_mb','nahal'],true)||$name===''||$amount<1500||$amount>1000000000||$units<1||$units>100000000)throw new RuntimeException('نام، قیمت، نوع و مقدار بسته را بررسی کنید.');return $this->accounts->change(function(&$s)use($id,$kind,$name,$amount,$units,$input){$s['catalog'][$id]=['id'=>$id,'name'=>$name,'kind'=>$kind,'price_toman'=>$amount,'units'=>$units,'enabled'=>!empty($input['enabled'])];});}
    public function checkout($id,$sku,$project,$request,$gatewayRequest=null){$a=$this->accounts->account($id);$p=$this->products()[$sku]??null;if(!$p||!SaaSAccounts::validId($request))throw new RuntimeException('بسته یا شناسهٔ خرید معتبر نیست.');if($p['kind']==='credits'&&!isset($a['projects'][$project]))throw new RuntimeException('پروژهٔ دریافت اعتبار را انتخاب کنید.');SaaSAccounts::assertActive($a);return $this->start($a,$p,$project,$request,$gatewayRequest);}
    public function renew($id,$cycle,$request,$gatewayRequest=null){$a=$this->accounts->account($id);$plan=ProjectPlans::find($a['plan_id']);if(!in_array($cycle,['monthly','yearly'],true))throw new RuntimeException('دوره معتبر نیست.');$price=(int)($plan['price_'.$cycle]??0);if($price<1500)throw new RuntimeException('قیمت تمدید تنظیم نشده است.');return $this->start($a,['id'=>$plan['id'].':'.$cycle,'name'=>'تمدید '.$plan['name'],'kind'=>'renew','price_toman'=>$price,'cycle'=>$cycle],null,$request,$gatewayRequest);}
    private function start($account,$product,$project,$request,$gatewayRequest){$site=getSiteSettings();if(empty($site['zarinpal_enabled'])||empty($site['zarinpal_merchant_id'])||!empty($site['zarinpal_sandbox']))throw new RuntimeException('درگاه واقعی پرداخت آماده نیست.');$currency=strtoupper($site['zarinpal_currency']??'IRT');if(!in_array($currency,['IRR','IRT'],true))throw new RuntimeException('واحد درگاه معتبر نیست.');$id=bin2hex(random_bytes(16));$key=hash('sha256',$account['id'].'|'.$request);$hash=hash('sha256',json_encode([$product,$project]));$row=['id'=>$id,'account'=>$account['id'],'project'=>$project,'product'=>$product,'state'=>'preparing','request'=>$key,'hash'=>$hash,'amount'=>$product['price_toman']*($currency==='IRR'?10:1),'currency'=>$currency,'gateway'=>array_intersect_key($site,array_flip(['zarinpal_enabled','zarinpal_merchant_id','zarinpal_sandbox','zarinpal_currency','zarinpal_access_token'])),'created_at'=>time()];
        $old=$this->accounts->change(function(&$s)use($row){foreach($s['orders']??[] as $old)if($old['request']===$row['request']){if($old['hash']!==$row['hash'])throw new RuntimeException('درخواست خرید با محتوای متفاوت تکرار شده است.');if(isset($old['url']))return $old['url'];throw new RuntimeException('وضعیت درخواست قبلی را بررسی کنید؛ برای جلوگیری از پرداخت تکراری درخواست جدید ایجاد نشد.');}$s['orders'][$row['id']]=$row;return null;});if($old)return $old;
        $gatewayRequest=$gatewayRequest?:'zarinpalRequestPayment';$r=$gatewayRequest($row['amount'],$product['name'],AiOAuth::base().'/panel/account_payment.php?id='.$id,'','',$id,$row['gateway']);if(empty($r['success'])||empty($r['authority'])||empty($r['payment_url']))throw new RuntimeException('درخواست پرداخت تأیید نشد؛ وضعیت خرید را بررسی کنید.');$this->accounts->change(function(&$s)use($id,$r){$s['orders'][$id]['authority']=$r['authority'];$s['orders'][$id]['url']=$r['payment_url'];$s['orders'][$id]['state']='pending';});return $r['payment_url'];}
    public function verify($id,$authority,$status,$verify=null){$order=$this->accounts->state()['orders'][$id]??null;if(!$order||!is_string($authority)||empty($order['authority'])||!hash_equals($order['authority'],$authority)||$status!=='OK')throw new RuntimeException('پرداخت لغو یا نامعتبر است.');if($order['state']==='paid')return $order;$verify=$verify?:'zarinpalVerifyPayment';$r=$verify($authority,$order['amount'],$order['gateway']);if(empty($r['success'])||empty($r['ref_id']))throw new RuntimeException('پرداخت توسط درگاه تأیید نشد.');return $this->accounts->change(function(&$s)use($id,$r){$o=&$s['orders'][$id];if($o['state']==='paid')return $o;foreach($s['orders'] as $otherId=>$other)if($otherId!==$id&&($other['ref_id']??'')===(string)$r['ref_id'])throw new RuntimeException('رسید قبلاً استفاده شده است.');$a=&$s['accounts'][$o['account']];$p=$o['product'];$kind=$p['kind'];if($kind==='credits'){$a['wallets'][$o['project']]['balance']=($a['wallets'][$o['project']]['balance']??0)+$p['units'];}elseif(in_array($kind,['projects','seats','storage_mb'],true))$a['limits'][$kind]+=$p['units'];elseif($kind==='nahal')$a['employees']['nahal']=($a['employees']['nahal']??0)+$p['units'];elseif($kind==='renew'){$a['expires_at']=SaaSAccounts::extendExpiry(max(time(),$a['expires_at']),$p['cycle']);}else throw new RuntimeException('نوع سفارش معتبر نیست.');$o['state']='paid';$o['ref_id']=(string)$r['ref_id'];$o['paid_at']=time();$s['audit'][]=['account'=>$a['id'],'action'=>'purchase_applied','order'=>$id,'at'=>time()];return $o;});}
}
